#!/usr/bin/env python3
# Checks on psi(GHB_2(7)) < SL_4(F_7), generators from GroupApproximation/Kazhdan/GHBQuotientMatrices.lean:
#   a = I + E_03 + E_12,  b = I + E_10 - E_23,  c = I + E_31.
# Reports: generator orders; F_7-span dimension of the generated matrix algebra (16 => absolutely irreducible);
# dimension of invariant bilinear forms; rank of c - I (transvection); irreducibility of the
# normal closure of c (span of algebra generated by conjugates of c).
import random
import numpy as np

p = 7
I4 = np.eye(4, dtype=np.int64)


def mat(entries):
    M = I4.copy()
    for (i, j, v) in entries:
        M[i, j] = (M[i, j] + v) % p
    return M


a = mat([(0, 3, 1), (1, 2, 1)])
b = mat([(1, 0, 1), (2, 3, -1)])
c = mat([(3, 1, 1)])
gens = [a, b, c]


def mul(X, Y):
    return (X @ Y) % p


def order(X):
    Y, k = X.copy(), 1
    while not np.array_equal(Y, I4):
        Y, k = mul(Y, X), k + 1
    return k


def rank_mod_p(rows):
    A = np.array(rows, dtype=np.int64) % p
    m, n = A.shape
    r = 0
    for col in range(n):
        piv = next((i for i in range(r, m) if A[i, col] % p), None)
        if piv is None:
            continue
        A[[r, piv]] = A[[piv, r]]
        A[r] = (A[r] * pow(int(A[r, col]), p - 2, p)) % p
        for i in range(m):
            if i != r and A[i, col]:
                A[i] = (A[i] - A[i, col] * A[r]) % p
        r += 1
    return r


def algebra_span_dim(generators, max_len=8):
    words, frontier, seen = [I4], [I4], {I4.tobytes()}
    for _ in range(max_len):
        new = []
        for X in frontier:
            for g in generators:
                Y = mul(X, g)
                k = Y.tobytes()
                if k not in seen:
                    seen.add(k)
                    new.append(Y)
        frontier = new
        words += new
        d = rank_mod_p([w.flatten() for w in words])
        if d == 16 or not new:
            return d
    return rank_mod_p([w.flatten() for w in words])


def invariant_bilinear_forms_dim(generators):
    # unknown B (16 entries); equations X^T B X - B = 0 for each generator X
    rows = []
    for X in generators:
        for i in range(4):
            for j in range(4):
                row = np.zeros(16, dtype=np.int64)
                for k in range(4):
                    for l in range(4):
                        row[4 * k + l] = (row[4 * k + l] + X[k, i] * X[l, j]) % p
                row[4 * i + j] = (row[4 * i + j] - 1) % p
                rows.append(row)
    return 16 - rank_mod_p(rows)


def random_element(generators, length, rng):
    X = I4.copy()
    for _ in range(length):
        X = mul(X, generators[rng.randrange(len(generators))])
    return X


def inverse(X):
    Y = I4.copy()
    for _ in range(order(X) - 1):
        Y = mul(Y, X)
    return Y


if __name__ == "__main__":
    print("generator orders", [order(g) for g in gens])
    print("rank(c - I) =", rank_mod_p([((c - I4) % p).flatten()]) if False else np.linalg.matrix_rank((c - I4) % p))
    print("algebra span dim of <a,b,c> =", algebra_span_dim(gens))
    print("invariant bilinear forms dim =", invariant_bilinear_forms_dim(gens))
    rng = random.Random(20260912)
    conj = []
    for _ in range(12):
        g = random_element(gens, 25, rng)
        conj.append(mul(mul(g, c), inverse(g)))
    print("algebra span dim of 12 random conjugates of c =", algebra_span_dim(conj, max_len=6))
    print("invariant bilinear forms dim for conjugates of c =", invariant_bilinear_forms_dim(conj))
    print("vertex images span dims <a,b>,<c,b>,<c,a> =",
          algebra_span_dim([a, b]), algebra_span_dim([c, b]), algebra_span_dim([c, a]))
